mapper.select:
select ar.id, ar.name as abattoir_name, COUNT(odl.id) as trade_slices, (case when COUNT(case when odl.weight >= ${param.standardWeight} then 1 end) is not null then COUNT(case when odl.weight >= ${param.standardWeight} then 1 end) else 0 end) as higher_standard_weight, (case when COUNT(case when odl.weight < ${param.standardWeight} then 1 end) is not null then COUNT(case when odl.weight < ${param.standardWeight} then 1 end) else 0 end) as lower_standard_weight, (case when MAX( odl.unit_price ) is not null then MAX( odl.unit_price ) else 0 end) as higher_amount, (case when MIN( odl.unit_price ) is not null then Min( odl.unit_price ) else 0 end) as lower_amount, --(case when AVG( odl.price ) is not null then AVG( odl.price ) else 0 end) as average_amount, --(case when AVG( case when odl.price > ${param.lowerPrice} then odl.price end ) is not null then AVG(case when --odl.price > ${param.lowerPrice} then odl.price end) else 0 end ) AS actual_amount, (case when SUM(odl.weight) is not null then SUM(odl.weight) else 0 end ) as deal_weight, (case when SUM(odl.price) is not null then SUM(odl.price) else 0 end ) as deal_amount, sum(if(odl.unit_price > ${param.lowerPrice},odl.price,0)) AS actual_amount, sum(if(odl.unit_price > ${param.lowerPrice},odl.weight,0)) AS actual_weight, (case when SUM(odl.commission) is not null then SUM(odl.commission) else 0 end ) as commission from abattoir ar left join meattrade_pork_report prt on ar.id = prt.abattoir_id left join meattrade_pork_arrange_detail padl on prt.code = padl.pork_report_code left join meattrade_order_detail odl on padl.id = odl.pork_arrange_detail_id left join meattrade_order o on odl.order_id = o.id
o.status = 'FINISHED'
and ar.name like concat("%",#{param.keyword},"%")
and odl.update_time between #{param.period.begin} and #{param.period.end}
group by ar.id
order by ${param.item} ${param.sort}

select ar.id, ar.name as abattoir_name, odl.goods_category_id, odl.goods_category_name, COUNT(odl.id) as trade_slices, -- (case when COUNT(case when odl.weight >= ${param.standardWeight} then 1 end) is not null then COUNT(case when -- odl.weight >= ${param.standardWeight} then 1 end) else 0 end) as higher_standard_weight, -- (case when COUNT(case when odl.weight < ${param.standardWeight} then 1 end) is not null then COUNT(case -- when -- odl.weight < ${param.standardWeight} then 1 end) else 0 end) as lower_standard_weight, (case when MAX( odl.unit_price ) is not null then MAX( odl.unit_price ) else 0 end) as higher_amount, (case when MIN( odl.unit_price ) is not null then Min( odl.unit_price ) else 0 end) as lower_amount, (case when SUM(odl.weight) is not null then SUM(odl.weight) else 0 end ) as deal_weight, (case when SUM(odl.price) is not null then SUM(odl.price) else 0 end ) as deal_amount, sum(if(odl.unit_price > ${param.lowerPrice},odl.price,0)) AS actual_amount, sum(if(odl.unit_price > ${param.lowerPrice},odl.weight,0)) AS actual_weight, (case when SUM(odl.commission) is not null then SUM(odl.commission) else 0 end ) as commission from abattoir ar left join meattrade_pork_report prt on ar.id = prt.abattoir_id left join meattrade_pork_arrange_detail padl on prt.code = padl.pork_report_code left join meattrade_order_detail odl on padl.id = odl.pork_arrange_detail_id left join meattrade_order o on odl.order_id = o.id
o.status = 'FINISHED'
and ar.name like concat("%",#{param.keyword},"%")
and odl.update_time between #{param.period.begin} and #{param.period.end}
and prt.goods_category_Id = #{param.goodsCategoryId}
group by ar.id,odl.goods_category_id
order by ${param.item} ${param.sort}

SELECT a.id, a.`name`, SUM( pa.slices ) AS slices, SUM( pa.weight ) AS weight FROM abattoir a LEFT JOIN meattrade_pork_report pr ON a.id = pr.abattoir_id LEFT JOIN meattrade_pork_arrange pa ON pr.id = pa.pork_report_id
pa.tenant = #{param.tenant}
and pa.pork_arrange_time between #{param.period.begin} and #{param.period.end}
GROUP BY a.id ORDER BY weight DESC

SELECT a.id, a.`name`, SUM( pa.slices ) AS slices, SUM( pa.weight ) AS weight FROM abattoir a LEFT JOIN meattrade_pork_report pr ON a.id = pr.abattoir_id LEFT JOIN meattrade_pork_arrange pa ON pr.id = pa.pork_report_id
pa.tenant = #{param.tenant}
and pa.pork_arrange_time between #{param.period.begin} and #{param.period.end}
GROUP BY a.id ORDER BY weight DESC
